def gen(rng):
    def fmt(a, b):
        return '%d\n%s\n%d\n%s' % (len(a), ' '.join(a), len(b), ' '.join(b))

    def split(s, pieces):
        pieces = max(1, min(pieces, len(s)))
        cuts = sorted(rng.sample(range(1, len(s)), pieces - 1)) if pieces > 1 else []
        out, prev = [], 0
        for c in cuts + [len(s)]:
            out.append(s[prev:c])
            prev = c
        return out

    def rs(n, k=26):
        return ''.join(rng.choice('abcdefghijklmnopqrstuvwxyz'[:k]) for _ in range(n))

    tests = [fmt(['a'], ['a']), fmt(['a'], ['b']), fmt(['ab', 'c'], ['a', 'bc']), fmt(['abc'], ['ab', 'c', 'd']),
             fmt(['aa', 'a'], ['a', 'aa']), fmt(['aa', 'a'], ['aaaa']), fmt(['abc', 'def'], ['abcdef']), fmt(['abcde'], ['abcdf'])]
    for _ in range(14):
        s = rs(rng.randint(1, 40), rng.choice([1, 2, 3, 26]))
        t = rng.random()
        s2 = s
        if t < 0.35:
            pass
        elif t < 0.55:
            i = rng.randrange(len(s))
            s2 = s[:i] + rng.choice('abcxyz') + s[i + 1:]
        elif t < 0.75:
            s2 = s + rs(rng.randint(1, 3), 2)
        elif t < 0.85 and len(s) > 1:
            s2 = s[:-rng.randint(1, len(s) - 1)]
        else:
            s2 = rs(len(s), 2)
        tests.append(fmt(split(s, rng.randint(1, 12)), split(s2, rng.randint(1, 12))))
    big = rs(500000, 3)
    tests.append(fmt(split(big, 100000), split(big, 100000)))
    tests.append(fmt([big], split(big, 100000)))
    tests.append(fmt(split(big, 100000), split(big[:-1] + ('a' if big[-1] != 'a' else 'b'), 99999)))
    tests.append(fmt(['a'] * 100000, ['a' * 100000]))
    tests.append(fmt(['a'] * 100000, ['a' * 99999 + 'b']))
    return tests
